await page.locator('button').filter({hasText:'Run Real Verification'}).focus();await page.keyboard.press('Enter');await page.keyboard.press('Tab');const focused=await page.evaluate(()=>document.activeElement.textContent);if(focused!=='Publish Verified Model and Code')throw Error('Unexpected keyboard order: '+focused);await page.keyboard.press('Enter');await page.keyboard.press('Tab');if(await page.evaluate(()=>document.activeElement.textContent)!=='Technical Preview and Differences')throw Error('Disabled undo is not skipped');await page.keyboard.press('Enter');const actions=await page.evaluate(()=>window.reviewActions);if(JSON.stringify(actions)!==JSON.stringify(['verify','apply','technical']))throw Error('Keyboard actions failed');
